@'
const FIXTURES = {
  MSFT: { symbol: "MSFT", fixture_price_usd: "123.45", source: "offline-fixture" },
  AAPL: { symbol: "AAPL", fixture_price_usd: "67.89", source: "offline-fixture" }
};

const accepted = value => ({ tag: "accepted", value });
const rejected = reason => ({ tag: "rejected", reason });

export function validateStructuredResponse(text) {
  if (typeof text !== "string") return rejected("output-not-text");
  let value;
  try {
    value = JSON.parse(text);
  } catch {
    return rejected("malformed-json");
  }
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return rejected("output-not-object");
  }
  const keys = Object.keys(value).sort();
  if (keys.length !== 2 || keys[0] !== "decision" || keys[1] !== "reason") {
    return rejected("additional-or-missing-output-key");
  }
  if (!["approve", "review", "reject"].includes(value.decision)) {
    return rejected("invalid-decision");
  }
  if (typeof value.reason !== "string") return rejected("invalid-reason");
  return accepted(value);
}

export function processModelResponse(context, response) {
  if (!context || typeof context !== "object" || Array.isArray(context)) {
    return rejected("bad-context");
  }
  if (!response || typeof response !== "object" || Array.isArray(response)) {
    return rejected("bad-response");
  }
  if (context.applicationPolicy?.syntheticLocalRefusal === true) {
    return rejected("refused");
  }
  if (response.status !== "requires_action") return rejected("incomplete");
  if (!Array.isArray(response.steps) || response.steps.length !== 1) {
    return rejected("incomplete");
  }
  const step = response.steps[0];
  if (!step || typeof step !== "object" || Array.isArray(step) || step.type !== "function_call") {
    return rejected("not-a-call");
  }
  if (step.name !== "lookup_stock") return rejected("tool-not-allowlisted");
  if (typeof step.id !== "string" || step.id.length === 0) {
    return rejected("missing-call-id");
  }
  if (step.id !== context.expectedCallId) return rejected("correlation-mismatch");
  let args;
  try {
    args = typeof step.arguments === "string"
      ? JSON.parse(step.arguments)
      : step.arguments;
  } catch {
    return rejected("malformed-arguments");
  }
  if (!args || typeof args !== "object" || Array.isArray(args)) {
    return rejected("arguments-not-object");
  }
  const keys = Object.keys(args).sort();
  if (keys.length !== 2 || keys[0] !== "max_results" || keys[1] !== "symbol") {
    return rejected("additional-or-missing-argument-key");
  }
  if (typeof args.symbol !== "string" || !/^[A-Z]{1,5}$/.test(args.symbol)) {
    return rejected("invalid-symbol");
  }
  if (!Number.isInteger(args.max_results) || args.max_results < 1 || args.max_results > 5) {
    return rejected("invalid-range");
  }
  if (args.symbol !== context.targetSymbol) return rejected("input-mismatch");
  if (context.authorized !== true) return rejected("unauthorized");
  const record = FIXTURES[args.symbol];
  if (!record) return rejected("fixture-not-found");
  return accepted({
    decision: "executed",
    functionResult: {
      type: "function_result",
      call_id: step.id,
      name: step.name,
      result: [{ type: "text", text: JSON.stringify(record) }]
    }
  });
}
