@'
import assert from "node:assert/strict";
import {
  validateStructuredResponse,
  processModelResponse
} from "./learner.mjs";

const accepted = value => ({ tag: "accepted", value });
const rejected = reason => ({ tag: "rejected", reason });
const records = {
  MSFT: { symbol: "MSFT", fixture_price_usd: "123.45", source: "offline-fixture" },
  AAPL: { symbol: "AAPL", fixture_price_usd: "67.89", source: "offline-fixture" }
};
const context = {
  targetSymbol: "MSFT",
  expectedCallId: "call-1",
  authorized: true
};
const call = (overrides = {}) => ({
  status: "requires_action",
  steps: [{
    type: "function_call",
    name: "lookup_stock",
    arguments: { symbol: "MSFT", max_results: 1 },
    id: "call-1",
    ...overrides
  }]
});
const success = (symbol, id) => accepted({
  decision: "executed",
  functionResult: {
    type: "function_result",
    call_id: id,
    name: "lookup_stock",
    result: [{ type: "text", text: JSON.stringify(records[symbol]) }]
  }
});

const cases = [
  ["valid", () => [
    validateStructuredResponse('{"decision":"approve","reason":"fixture only"}'),
    processModelResponse(context, call())
  ], [
    accepted({ decision: "approve", reason: "fixture only" }),
    success("MSFT", "call-1")
  ]],
  ["wrong type", () => [
    validateStructuredResponse('{"decision":7,"reason":"bad type"}'),
    processModelResponse(context, call({ arguments: { symbol: 7, max_results: 1 } }))
  ], [rejected("invalid-decision"), rejected("invalid-symbol")]],
  ["unknown/additional keys", () => [
    validateStructuredResponse('{"decision":"approve","reason":"x","admin":true}'),
    processModelResponse(context, call({ arguments: { symbol: "MSFT", max_results: 1, admin: true } }))
  ], [
    rejected("additional-or-missing-output-key"),
    rejected("additional-or-missing-argument-key")
  ]],
  ["null", () => [
    validateStructuredResponse("null"),
    processModelResponse(context, null)
  ], [rejected("output-not-object"), rejected("bad-response")]],
  ["array", () => [
    validateStructuredResponse("[]"),
    processModelResponse(context, [])
  ], [rejected("output-not-object"), rejected("bad-response")]],
  ["malformed JSON", () => [
    validateStructuredResponse("{"),
    processModelResponse(context, call({ arguments: "{" }))
  ], [rejected("malformed-json"), rejected("malformed-arguments")]],
  ["range/domain violation", () =>
    processModelResponse(context, call({ arguments: { symbol: "msft", max_results: 0 } })),
    rejected("invalid-symbol")],
  ["unknown tool and unauthorized", () => [
    processModelResponse(context, call({ name: "delete_stock" })),
    processModelResponse({ ...context, authorized: false }, call())
  ], [rejected("tool-not-allowlisted"), rejected("unauthorized")]],
  ["wrong correlation", () =>
    processModelResponse(context, call({ id: "other-call" })),
    rejected("correlation-mismatch")],
  ["refusal and incomplete", () => [
    // Explicit synthetic local policy signal, not a provider wire status.
    processModelResponse(
      { ...context, applicationPolicy: { syntheticLocalRefusal: true } },
      { status: "completed", steps: [] }
    ),
    processModelResponse(context, { status: "requires_action", steps: [] })
  ], [rejected("refused"), rejected("incomplete")]],
  ["changed input positive and negative", () => {
    const aaplCall = call({
      arguments: { symbol: "AAPL", max_results: 1 },
      id: "call-a"
    });
    return [
      processModelResponse({ targetSymbol: "AAPL", expectedCallId: "call-a", authorized: true }, aaplCall),
      processModelResponse({ targetSymbol: "MSFT", expectedCallId: "call-a", authorized: true }, aaplCall)
    ];
  }, [success("AAPL", "call-a"), rejected("input-mismatch")]]
];

let failed = 0;
for (const [name, run, expected] of cases) {
  try {
    const actual = run();
    assert.deepStrictEqual(actual, expected);
    console.log(`PASS ${name}`);
  } catch {
    failed += 1;
    console.log(`FAIL ${name}`);
  }
}
console.log(`SUMMARY passed=${cases.length - failed} failed=${failed}`);
process.exitCode = failed === 0 ? 0 : 1;
